@ ============================================================================
@ gbamod2_data.s -- GBAModPlay v2 sound data of Aero the Acro-Bat: Rascal Rival Revenge (E)
@ ROM range 0x08036220-0x08103294, rebuilt byte for byte by gbamod2.mk:
@   0x08036220  22 modules ("GBAMOD2.", uncompressed 4-byte cells, samples not included)
@   0x0809B410  sample bank (31 headers + PCM in gbamod2_samples.bin), shared by all modules
@   0x080A6040  SFX bank (78 effects, PCM in gbamod2_sfx.bin)
@
@ Module layout: +0x00 "GBAMOD2."  +0x08 channels  +0x0C pattern bytes  +0x10 sample bytes
@   +0x14 mix rate  +0x18 song length  +0x1C u32 step[976]  +0xF5C u16 period[976]
@   +0x16FC 31 sample headers {len, finetune, volume, loopStart, loopLen, 0}  +0x1870 patterns
@   +0x1874 order list[128]  +0x18F4 u32 rows[64]  +0x19F4 unused[256]  +0x1AF4 s32 flag
@   (< 0: ignore the bank, use samples after the patterns)  +0x1AF8 pattern data
@ A row is one line: R  note,ins,cmd,par  for each channel.  note is an index into the period
@ table in 1/8 semitones: 8 = C_0 (period 1712 in the table's doubled units), 104 = C_1 (856,
@ ProTracker C-1), 200 = C_2 (428, 8287 Hz); NONE = 0x1FF; ins 0 = none.
@ ============================================================================
	.syntax unified
	.macro CELL note, ins, cmd, par
	.hword (\ins << 9) | \note, (0x\cmd << 8) | 0x\par
	.endm
	.macro R note, ins, cmd, par, rest:vararg
	CELL \note, \ins, \cmd, \par
	.ifnb \rest
	R \rest
	.endif
	.endm
	.equ	NONE, 0x1FF
	.equ	C_0, 8
